enc=lambda s: u.quote(s, safe="-_.!~*'()")
for k,r in repos.items():
    for i in r["issues"]:
        if "description" in i: n=len(enc(i["title"]))+len(enc(i["description"]))+len(enc(i["code"]))+len(enc(i["traceback"]))+len(enc(i["versions"]))
        else: n=len(enc(i["title"]))+len(enc(i["body"]))
        print(f"{k:12} {i['id']:6} prefill length ~{n+80}")
    for p in r["prs"]: print(f"{k:12} PR {p['id']:5} ~{len(enc(p['title']))+len(enc(p['body']))+80}")
